-- ==============================================================================
-- FlirtEasy Database Migration (Supabase PostgreSQL)
-- Target: New Supabase Project for FlirtEasy Mobile + Desktop Ecosystem
-- Generated: 2026-08-31T11:04:21.726Z
-- ==============================================================================

-- 1. Enable required extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- ==============================================================================
-- 2. CREATE EMPTY TABLES
-- ==============================================================================

-- 2.1 USERS TABLE
CREATE TABLE IF NOT EXISTS public.users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT,
    full_name TEXT,
    plan TEXT DEFAULT 'trial',
    subscription_status VARCHAR(50) DEFAULT 'trial',
    trial_started_at TIMESTAMPTZ DEFAULT now(),
    trial_likes_used INTEGER DEFAULT 0,
    trial_messages_used INTEGER DEFAULT 0,
    plan_expires_at TIMESTAMPTZ,
    stripe_customer_id TEXT,
    stripe_subscription_id VARCHAR(100),
    cancelled_at TIMESTAMPTZ,
    is_banned BOOLEAN DEFAULT false,
    is_admin BOOLEAN DEFAULT false,
    reset_token TEXT,
    reset_token_expires_at TIMESTAMPTZ,
    whatsapp_number TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- Index for fast user lookup
CREATE INDEX IF NOT EXISTS idx_users_email ON public.users(email);
CREATE INDEX IF NOT EXISTS idx_users_plan ON public.users(plan);

-- 2.2 CONFIG TABLE (System settings & Prompt / AI configurations)
CREATE TABLE IF NOT EXISTS public.config (
    key TEXT PRIMARY KEY,
    value JSONB NOT NULL DEFAULT '{}'::jsonb,
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- 2.3 USER SNAPSHOTS TABLE (Real-time bot state, settings, stats per user)
CREATE TABLE IF NOT EXISTS public.user_snapshots (
    user_id UUID PRIMARY KEY REFERENCES public.users(id) ON DELETE CASCADE,
    platform TEXT DEFAULT 'tinder',
    last_seen_at TIMESTAMPTZ DEFAULT now(),
    is_active BOOLEAN DEFAULT false,
    settings JSONB DEFAULT '{}'::jsonb,
    stats JSONB DEFAULT '{}'::jsonb,
    profile JSONB DEFAULT '{}'::jsonb,
    agent_state JSONB DEFAULT '{}'::jsonb,
    updated_at TIMESTAMPTZ DEFAULT now()
);

-- 2.4 USER EVENTS TABLE (Analytics & audit trail of likes, messages, matches)
CREATE TABLE IF NOT EXISTS public.user_events (
    id BIGSERIAL PRIMARY KEY,
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL,
    platform TEXT DEFAULT 'tinder',
    payload JSONB DEFAULT '{}'::jsonb,
    client_ts TIMESTAMPTZ DEFAULT now(),
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_user_events_user_id ON public.user_events(user_id);
CREATE INDEX IF NOT EXISTS idx_user_events_type ON public.user_events(event_type);
CREATE INDEX IF NOT EXISTS idx_user_events_created_at ON public.user_events(created_at);

-- 2.5 EMAIL QUEUE TABLE (Automated onboarding email drip sequences)
CREATE TABLE IF NOT EXISTS public.email_queue (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    user_email TEXT NOT NULL,
    user_name TEXT,
    email_index INTEGER NOT NULL DEFAULT 0,
    scheduled_at TIMESTAMPTZ NOT NULL,
    sent_at TIMESTAMPTZ,
    status TEXT DEFAULT 'pending',
    error_message TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_email_queue_status_sched ON public.email_queue(status, scheduled_at);
CREATE INDEX IF NOT EXISTS idx_email_queue_user ON public.email_queue(user_id);

-- 2.6 COMMUNITY CODES TABLE (Promo & referral code management)
CREATE TABLE IF NOT EXISTS public.community_codes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
    code TEXT UNIQUE NOT NULL,
    claimed BOOLEAN DEFAULT false,
    claimed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 2.7 AUDIT LOGS TABLE (Admin actions & security audit trail)
CREATE TABLE IF NOT EXISTS public.audit_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    action TEXT NOT NULL,
    target_type TEXT,
    target_id TEXT,
    target_label TEXT,
    details JSONB DEFAULT '{}'::jsonb,
    admin_email TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);

-- 2.8 ERROR LOGS TABLE (Selector breaks, runtime diagnostics)
CREATE TABLE IF NOT EXISTS public.error_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.users(id) ON DELETE SET NULL,
    platform TEXT DEFAULT 'tinder',
    error_type TEXT,
    selector_key TEXT,
    error_message TEXT,
    page_url TEXT,
    occurred_at TIMESTAMPTZ DEFAULT now()
);

-- 2.9 ERROR ISSUE STATUS TABLE (Track fixed vs open UI selector issues)
CREATE TABLE IF NOT EXISTS public.error_issue_status (
    issue_key TEXT PRIMARY KEY,
    platform TEXT DEFAULT 'tinder',
    error_type TEXT,
    selector_key TEXT,
    status TEXT DEFAULT 'open',
    updated_at TIMESTAMPTZ DEFAULT now(),
    updated_by TEXT
);

-- 2.10 USER PUSH TOKENS TABLE (Device push token registry for mobile alerts)
CREATE TABLE IF NOT EXISTS public.user_push_tokens (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    push_token TEXT UNIQUE NOT NULL,
    platform TEXT DEFAULT 'ios',
    device_name TEXT,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_push_tokens_user ON public.user_push_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_push_tokens_token ON public.user_push_tokens(push_token);

-- 2.11 NOTIFICATIONS HISTORY TABLE (In-app notification center inbox)
CREATE TABLE IF NOT EXISTS public.notifications_history (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES public.users(id) ON DELETE CASCADE,
    type TEXT NOT NULL, -- 'goal_unlocked', 'new_match', 'cycle_complete', 'safety_cooldown', 'digest'
    title TEXT NOT NULL,
    body TEXT NOT NULL,
    data JSONB DEFAULT '{}'::jsonb,
    is_read BOOLEAN DEFAULT false,
    created_at TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_notif_user_created ON public.notifications_history(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_notif_user_unread ON public.notifications_history(user_id, is_read);

-- ==============================================================================
-- 3. ROW LEVEL SECURITY (RLS) & ACCESS POLICIES
-- ==============================================================================
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.config ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.email_queue ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.community_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.error_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.error_issue_status ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.user_push_tokens ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.notifications_history ENABLE ROW LEVEL SECURITY;

-- Allow Service Role (Cloudflare Worker & backend) full access
DO $$
BEGIN
    CREATE POLICY "Service role full access on users" ON public.users FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on user_snapshots" ON public.user_snapshots FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on user_events" ON public.user_events FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on config" ON public.config FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on email_queue" ON public.email_queue FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on community_codes" ON public.community_codes FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on audit_logs" ON public.audit_logs FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on error_logs" ON public.error_logs FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on error_issue_status" ON public.error_issue_status FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on user_push_tokens" ON public.user_push_tokens FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Service role full access on notifications_history" ON public.notifications_history FOR ALL TO service_role USING (true) WITH CHECK (true);
    CREATE POLICY "Public read and write push tokens" ON public.user_push_tokens FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    CREATE POLICY "Public read and write notifications" ON public.notifications_history FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    CREATE POLICY "Public insert user_events" ON public.user_events FOR INSERT TO anon, authenticated WITH CHECK (true);
    CREATE POLICY "Public read user_events" ON public.user_events FOR SELECT TO anon, authenticated USING (true);
    CREATE POLICY "Public read and write user_snapshots" ON public.user_snapshots FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
    CREATE POLICY "Public read and write users" ON public.users FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

-- Allow public read access to active config keys (e.g. feature flags, rate limits)
DO $$
BEGIN
    CREATE POLICY "Public read config" ON public.config FOR SELECT TO anon, authenticated USING (true);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

