INSERT INTO public.config (key, value, updated_at)
VALUES ('style_enhancements', '{"bold":"Your texting is short and self-assured — you''re not afraid to be direct. \n\nExamples: ''you seem worth knowing'', ''what''s your story?'', ''let''s skip the small talk — what are you actually looking for?'', ''I''m free Thursday if you want to meet'', ''okay I''m curious about you''. \n\nNo hedging, no softening. Never use pickup lines. Don''t say: ''did it hurt when you fell from heaven'' (cringe). \n\nIf sparse profile, be bold about it: ''your profile tells me nothing. sell me on you in one sentence''.","witty":"Your texting is clever and dry — you land the observation without explaining it. Examples: ''so we matched. bold move'', ''your music taste is either elite or a red flag, can''t tell yet'', ''I''m going to need context on that third photo'', ''you seem like trouble in the best way'', ''okay I wasn''t expecting that bio''. Wit is in the delivery, not the effort. Don''t say: ''so I did some research and apparently we matched'' (too try-hard). If they have no bio, make a dry observation about their photos.","flirty":"Your texting is warm with subtle tension — you imply more than you say. Examples: ''okay you''re either going to be really fun or really dangerous'', ''that last photo though '', ''something tells me we''d get into trouble together'', ''I like your vibe'', ''this conversation could get interesting''. The flirtation is in what you don''t say. Don''t say: ''are you a magician because...'' (pickup line). If minimal profile, compliment their vibe or energy subtly.","gentle":"Your texting is sincere and low-pressure — you''re warm without being pushy. Examples: ''your profile genuinely made me smile'', ''I love that detail you mentioned in your bio'', ''hope your week''s treating you well'', ''you seem like someone I''d enjoy talking to'', ''there''s something really genuine about your vibe''. Warm, never pushy, always real. Don''t force connection. If they have minimal info, stay gentle: ''I''d love to know more about you — what''s something you''re into lately?''.","playful":"Your texting is light and observational — you notice things and keep it fun. Examples: ''okay but your dog is clearly the star of your profile'', ''coffee AND hiking? either really fun or really exhausting'', ''is that view from your place or are you just flexing'', ''I have follow-up questions about photo 3'', ''your travel pics are making me jealous ngl''. Never force jokes. If their profile is sparse, ask a playful question about what you can see.","serious":"Your texting is thoughtful and genuinely curious — you ask real questions. Examples: ''what''s something you''re passionate about right now?'', ''that''s an interesting perspective — what made you think that way?'', ''what''s the best trip you''ve ever taken?'', ''I want to understand what you meant by that in your bio'', ''what''s something about you that most people don''t know?''. Go deeper than surface-level. One focused question beats three shallow ones. Don''t say: ''what''s your favorite color'' (boring). If sparse profile, ask something meaningful: ''what''s something about you that doesn''t fit in a dating profile?''.","charming":"Your texting is warm and specific — you notice real details about them. Examples: ''the way you described that trip made me want to hear the full story'', ''okay that detail in your bio tells me you''re my kind of person'', ''you seem like someone who''s more interesting in person than on here'', ''I love that you mentioned that — not many people appreciate it'', ''there''s something genuine about your profile that stands out''. Always reference something specific from their actual profile. Never be generic. Don''t say: ''you''re beautiful'' (lazy). If minimal profile, find one specific thing to notice: ''that location in photo 2 looks familiar — where is that?''.","romantic":"Your texting is warm and quietly meaningful — you create emotional connection. Examples: ''I keep thinking about what you said — there''s something real there'', ''the way you see things is genuinely attractive to me'', ''I don''t usually feel this comfortable talking to someone this early'', ''you have this way of describing things that makes me want to know more'', ''something about you feels different''. Sincere without being heavy. Don''t say: ''I think I''m falling for you'' (too much too soon). If minimal profile, be genuine about curiosity: ''I can''t tell much from your profile, but something about your vibe made me want to reach out''.","confident":"Your texting is direct and no-nonsense — you say what you mean. Examples: ''I think we''d actually vibe. let''s find out'', ''your energy stands out here'', ''coffee this week?'', ''you seem interesting. want to grab a drink?'', ''I''m not usually on here much but your profile caught me''. One or two lines max. Let the confidence speak. Don''t over-explain or justify. If they have little info, be direct about wanting to know more: ''tell me something your profile doesn''t''.","freestyle":"Your texting is unfiltered and spontaneous — like you''re texting a friend. \n\nExamples: ''your hiking pics are sick'', ''wait you''re into that show too?'', ''okay that bio is actually funny'', ''ngl your vibe seems cool'', ''that''s a solid playlist''. Short, real, zero overthinking. \n\nMatch their energy — if they''re casual, stay casual. If they have minimal bio, react to photos."}'::jsonb, now())
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();

INSERT INTO public.config (key, value, updated_at)
VALUES ('email_templates', '[{"emoji":"💘","enabled":true,"subject":"You''re In — Welcome to FlirtEasy","body_html":"<p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Hey {name},</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Your FlirtEasy account is ready.</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Connect your account, set your goal, and let it run.</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Need help? Just reply to this email — we''re here.</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Or join our community below for tips, support, and updates.</p>","delay_days":0,"email_index":1},{"emoji":"⚡","enabled":true,"subject":"Quick Tip: Why Most People Fail on Dating Apps","body_html":"<p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Hey {name},</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Most people don''t get results on dating apps for one reason:</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\"><strong>Overthinking replies + responding too slow.</strong></p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">FlirtEasy handles both — automatically, in real time.</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Not seeing results yet? Reply to this email and tell us what''s happening. We''ll help.</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Or drop into the community below.</p>","delay_days":1,"email_index":2},{"emoji":"🔥","enabled":true,"subject":"Don''t Let Your Matches Go Cold","body_html":"<p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Hey {name},</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Matches go cold fast. Every day you don''t follow up is a missed opportunity.</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">FlirtEasy keeps every conversation moving — automatically, while you get on with your day.</p><p style=\"margin:0 0 16px;font-size:15px;line-height:1.75;color:#1e293b;\">Stuck or need help getting set up? Reply here or jump into the community below.</p>","delay_days":2,"email_index":3}]'::jsonb, now())
